import re
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Tuple

import requests


_PROVIDER_API_HOST = "https://api.openai.com"
_PROVIDER_ENV_VAR = "OPENAI_API_KEY"


@dataclass
class CorpusSafetyResult:
    safe: bool
    score: float
    reasons: List[str]
    categories: Dict[str, float]
    provider: str = "openai"
    model: str = "omni-moderation-latest"


class CorpusSafetyError(RuntimeError):
    pass


def _get_api_key(api_key: Optional[str] = None) -> str:
    key = api_key or os.getenv(_PROVIDER_ENV_VAR)
    if not key:
        raise CorpusSafetyError(f"Missing {_PROVIDER_ENV_VAR}")
    return key


def _normalize_text(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip()


def _chunk_text(text: str, max_chars: int = 8000) -> List[str]:
    text = _normalize_text(text)
    if not text:
        return [""]
    return [text[i : i + max_chars] for i in range(0, len(text), max_chars)]


def _moderate(text: str, api_key: str, model: str) -> Dict:
    resp = requests.post(
        f"{_PROVIDER_API_HOST}/v1/moderations",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={"model": model, "input": text},
        timeout=30,
    )
    if resp.status_code >= 400:
        raise CorpusSafetyError(f"Moderation request failed: {resp.status_code} {resp.text}")
    return resp.json()


def check_corpus_text(
    text: str,
    api_key: Optional[str] = None,
    model: str = "omni-moderation-latest",
    threshold: float = 0.5,
) -> CorpusSafetyResult:
    key = _get_api_key(api_key)
    chunks = _chunk_text(text)
    reasons: List[str] = []
    categories: Dict[str, float] = {}
    max_score = 0.0
    safe = True

    for chunk in chunks:
        result = _moderate(chunk, key, model)
        item = (result.get("results") or [{}])[0]
        flagged = bool(item.get("flagged"))
        category_scores = item.get("category_scores") or {}
        for cat, score in category_scores.items():
            categories[cat] = max(categories.get(cat, 0.0), float(score))
            max_score = max(max_score, float(score))
        if flagged:
            safe = False
            flagged_categories = item.get("categories") or {}
            for cat, is_flagged in flagged_categories.items():
                if is_flagged:
                    reasons.append(cat)

    if max_score >= threshold:
        safe = False

    reasons = sorted(set(reasons))
    return CorpusSafetyResult(
        safe=safe,
        score=max_score,
        reasons=reasons,
        categories=categories,
        provider="openai",
        model=model,
    )


def corpus_is_safe(text: str, api_key: Optional[str] = None, threshold: float = 0.5) -> bool:
